import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import vm from 'node:vm';
const source=['EvaluationLedger.gs','FormsEvaluation.gs'].map(f=>readFileSync(new URL(`../apps-script-v2/${f}`,import.meta.url),'utf8')).join('\n');
const clone=value=>structuredClone(value);
const plain=value=>JSON.parse(JSON.stringify(value));
const sha=value=>createHash('sha256').update(value).digest('hex');
const FORM='FormFixture123456',ALIAS='PublicFixture123456',AREA='future-area';
const profile=(uid,extra={})=>({id:uid,uid,active:true,access:true,role:'usuario',email:`${uid}@example.invalid`,permissions:{},...extra});
const question=(id,title,points=0,extra={})=>({itemId:`item-${id}`,title,questionItem:{question:{questionId:id,required:false,grading:{pointValue:points,...(points?{correctAnswers:{answers:[{value:'A'}]}}:{})},...(points?{choiceQuestion:{type:'RADIO',options:[{value:'A'},{value:'B'}]}}:{textQuestion:{paragraph:true}}),...extra}}});
function metadata(){return{formId:FORM,responderUri:`https://docs.google.com/forms/d/e/${ALIAS}/viewform`,info:{title:'Matéria fictícia'},settings:{emailCollectionType:'VERIFIED',quizSettings:{isQuiz:true}},items:[question('ack','[SAHMT:ACK] Ciência',0,{choiceQuestion:{type:'RADIO',options:[{value:'SIM'},{value:'NÃO'}]}}),question('problem','[SAHMT:SUGGESTION_PROBLEM] Problema'),question('proposal','[SAHMT:SUGGESTION_PROPOSAL] Proposta'),question('benefit','[SAHMT:SUGGESTION_BENEFIT] Benefício'),question('test','Questão clínica fictícia',5)]};}
const answer=value=>({textAnswers:{answers:[{value}]}});
function harness(){
  const store=new Map(),props=new Map(),forms=new Map(),google=new Map(),queries=[],awards=[],commits=[],operatorChecks=[];let serial=0,enabled=true;
  const ctx=vm.createContext({Date,Map,Set,JSON,Number,Object,Array,String,RegExp,Error,Math,encodeURIComponent,decodeURIComponent,
    Utilities:{DigestAlgorithm:{SHA_256:'SHA_256'},Charset:{UTF_8:'UTF_8'},getUuid:()=> 'test-uuid-'+(++serial),computeDigest:(_,text)=>Array.from(createHash('sha256').update(text).digest()),formatDate:date=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(date)},
    PropertiesService:{getScriptProperties:()=>({getProperty:key=>props.get(key)||null,setProperty:(key,value)=>props.set(key,value),deleteProperty:key=>props.delete(key)})},
    LockService:{getScriptLock:()=>({tryLock:()=>true,releaseLock:()=>{}})},
    ScriptApp:{getOAuthToken:()=> 'fake-no-live-token',getProjectTriggers:()=>[],newTrigger:()=>{throw Error('No real triggers in tests');}},
    FormApp:{openById:id=>{if(!forms.has(id))throw Error('Missing mocked form');return forms.get(id);},openByUrl:url=>{const form=Array.from(forms.values()).find(f=>f.responderUrl===url);if(!form)throw Error('Unknown public alias');return form;}}});
  vm.runInContext(source,ctx);
  const nativeQuery=ctx.evaluationQuery_,nativeGoogleRequest=ctx.formsEvaluationGoogleRequest_;
  ctx.sha256Hex_=sha;
  ctx.firestoreFilter_=(field,op,value)=>({field:{fieldPath:field},op,value});
  const key=(c,id)=>`${c}/${id}`;
  function seed(c,id,fields){store.set(key(c,id),{...clone(fields),id,_documentName:`projects/fake/databases/(default)/documents/${c}/${id}`,_updateTime:`v${++serial}`});}
  function get(c,id){return store.has(key(c,id))?clone(store.get(key(c,id))):null;}
  function commit(writes){for(const w of writes){const current=store.get(key(w.c,w.id));if(w.previous===null&&current||w.previous?._updateTime&&w.previous._updateTime!==current?._updateTime)throw Error('CAS');}for(const w of writes){const old=get(w.c,w.id)||{};const patch=clone(w.changes);for(const name of w.times)patch[name]=new Date();seed(w.c,w.id,{...old,...patch});}commits.push(writes);}
  ctx.evaluationGet_=get;
  ctx.firestoreDocumentName_=(c,id)=>`projects/fake/databases/(default)/documents/${c}/${id}`;
  ctx.evaluationQuery_=(c,filters=[],order=[],limit=100,projection=null,tx=null,cursor=null)=>{
    queries.push({c,filters:clone(filters),order:clone(order),tx,cursor:clone(cursor)});
    let docs=Array.from(store.entries()).filter(([k])=>k.startsWith(`${c}/`)).map(([,value])=>clone(value));
    const field=(d,path)=>path==='__name__'?d._documentName:path.split('.').reduce((value,key)=>value?.[key],d);
    const comparable=value=>value instanceof Date?value.getTime():value;
    for(const f of filters){assert.ok(f.field,'engine accepts raw filters only');const target=f.value.stringValue??f.value.referenceValue??f.value.booleanValue??(f.value.integerValue===undefined?undefined:Number(f.value.integerValue));docs=docs.filter(d=>{const value=comparable(field(d,f.field.fieldPath));return f.op==='EQUAL'?value===target:f.op==='GREATER_THAN'?value>target:false;});}
    const ordering=order.length?order:[{fieldPath:'__name__',direction:'ASCENDING'}];
    docs.sort((a,b)=>{for(const criterion of ordering){const one=comparable(field(a,criterion.fieldPath)),two=comparable(field(b,criterion.fieldPath));if(one===two)continue;return (one<two?-1:1)*(criterion.direction==='DESCENDING'?-1:1);}return 0;});
    if(cursor){const date=new Date(cursor.values[0].timestampValue).getTime(),name=cursor.values[1].referenceValue;docs=docs.filter(d=>{const time=new Date(d.createdAt).getTime();return time>date||time===date&&d._documentName>name;});}
    return docs.slice(0,limit);
  };
  ctx.evaluationWrite_=(c,id,changes,previous=null,times=[])=>({c,id,changes:clone(changes),previous:clone(previous),times});
  ctx.evaluationRunTransaction_=callback=>{const p=callback('mock-transaction');commit(p.writes||[]);return p.result;};
  ctx.formsEvaluationCommitWrites_=commit;
  ctx.evaluationAssertOperator_=runtime=>{operatorChecks.push(runtime);if(runtime&&!enabled)throw Error('Homologação e ativação pendentes');return 'admin@example.invalid';};
  ctx.formsEvaluationGoogleRequest_=url=>{const route=google.get(url);if(route instanceof Error)throw route;if(route===undefined)throw Error(`Unexpected mocked Google URL ${url}`);return typeof route==='function'?clone(route()):clone(route);};
  ctx.evaluationApplyAwards_=(changes,options={})=>{const writes=[],plans=[];for(const change of changes){awards.push(clone(change));const id=ctx.evaluationAwardId_(change),old=get('evaluationAwards',id);const plan=ctx.evaluationPlanAward_(old,change);plans.push(plan);if(plan.changed){writes.push(ctx.evaluationWrite_('evaluationAwards',id,plan.award,old),ctx.evaluationWrite_('evaluationLedger',plan.ledger.id,plan.ledger,null));}}return{status:plans.some(p=>p.status==='NEEDS_REVIEW')?'NEEDS_REVIEW':'APPLIED',writes,awards:plans};};
  function fakeForm(id=FORM){const obj={getId:()=>id,responderUrl:`https://docs.google.com/forms/d/e/${ALIAS}/viewform`,hasLimitOneResponsePerUser:()=>true,canEditResponse:()=>false,isAcceptingResponses:()=>true,supportsAdvancedResponderPermissions:()=>true,isPublished:()=>true};forms.set(id,obj);return obj;}
  function seedFixture(){seed('users','admin',profile('admin',{permissions:{admin:true}}));seed('users','manager',profile('manager'));seed('users','person',profile('person'));seed('managementAreas',AREA,{active:true,managerUids:['preserved-legacy']});seed('evaluationAssignments',AREA,{areaId:AREA,uid:'manager',version:1,effectiveAt:new Date('2026-01-01')});seed('evaluationAssignmentHistory',`assignment-${ctx.formsEvaluationHash_(`${AREA}\0${1}`)}`,{areaId:AREA,uid:'manager',version:1,effectiveAt:new Date('2026-01-01')});seed('evaluationActivities',FORM,{formId:FORM,active:true,areaIds:[AREA],status:'CONFIGURATION_PENDING'});const meta=metadata();google.set(`https://forms.googleapis.com/v1/forms/${FORM}`,meta);fakeForm();return meta;}
  function configuration(meta=metadata(),extra={}){const checked=ctx.formsEvaluationConfiguration_(meta,{modalities:{acknowledgement:true,suggestion:true,test:true}});const cfg={formId:FORM,status:'READY',creditScopeId:'matter',version:1,configVersion:1,eligibleUids:['person','manager'],managerAreaId:AREA,managerUid:'manager',assignmentId:AREA,modalities:{acknowledgement:true,suggestion:true,test:true},...checked,materialUrls:[],materialSnapshot:[],materialFingerprint:ctx.formsEvaluationHash_([]),validFrom:new Date('2026-01-01'),validUntil:new Date('2099-12-31'),firstEligibleAt:new Date('2026-01-01'),...extra};seed('evaluationFormConfigs',FORM,cfg);seed('evaluationActivities',FORM,{...(get('evaluationActivities',FORM)||{}),formId:FORM,active:true,status:'READY',configVersion:cfg.configVersion,managerUid:cfg.managerUid,managerAreaId:cfg.managerAreaId,assignmentId:cfg.assignmentId,areaIds:[AREA]});return cfg;}
  function response(extra={}){return{formId:FORM,responseId:'response-fixture',respondentEmail:'person@example.invalid',createTime:new Date().toISOString(),answers:{ack:answer('SIM'),test:answer('A')},totalScore:5,...extra};}
  return{ctx,nativeQuery,nativeGoogleRequest,store,seed,get,commit,props,forms,google,queries,awards,commits,operatorChecks,seedFixture,configuration,response,fakeForm,enable:value=>{enabled=value;},values:c=>Array.from(store.entries()).filter(([k])=>k.startsWith(`${c}/`)).map(([,v])=>clone(v))};
}
function run(h,method,payload,actor='admin'){return h.ctx.evaluationRunTransaction_(tx=>h.ctx[method](payload,actor,tx));}
function setResponse(h,response){h.google.set(`https://forms.googleapis.com/v1/forms/${FORM}/responses/${response.responseId}`,response);return response;}
function govPayload(extra={}){return{activityId:FORM,areaId:AREA,assignmentId:AREA,previousVersion:1,newVersion:2,summary:'Alteração concreta e pertinente dos itens.',components:['QUESTIONS'],materialEvidence:[],questionEvidence:[`https://docs.google.com/forms/d/${FORM}/edit`],...extra};}
function changedQuestions(h){const meta=h.seedFixture();h.configuration(meta);meta.items.find(q=>q.itemId==='item-test').title='Questão alterada de maneira efetiva';h.google.set(`https://forms.googleapis.com/v1/forms/${FORM}`,meta);h.google.set(`https://www.googleapis.com/drive/v3/files/${FORM}?fields=id,modifiedTime,lastModifyingUser(emailAddress)`,{id:FORM,modifiedTime:new Date().toISOString(),lastModifyingUser:{emailAddress:'manager@example.invalid'}});return meta;}

test('arquivo define adaptador sem chamar APIs, atribuir créditos ou instalar gatilhos',()=>{const h=harness();assert.equal(h.commits.length,0);assert.equal(h.awards.length,0);assert.equal(h.store.size,0);});
test('normalização backend distingue Forms real de alias público/curto',()=>{const h=harness();assert.equal(h.ctx.formsEvaluationLink_(`https://docs.google.com/forms/d/${FORM}/edit`).formId,FORM);assert.equal(h.ctx.formsEvaluationLink_(`https://docs.google.com/forms/d/e/${ALIAS}/viewform`).formId,null);assert.equal(h.ctx.formsEvaluationLink_('https://forms.gle/TestAlias').kind,'SHORT_URL');});
test('resolução de alias exige responderUri e mantém origem canônica',()=>{const h=harness();h.seedFixture();const r=h.ctx.formsEvaluationResolve_(h.ctx.formsEvaluationLink_(`https://docs.google.com/forms/d/e/${ALIAS}/viewform`),{});assert.equal(r.formId,FORM);h.forms.get(FORM).responderUrl='https://docs.google.com/forms/d/e/DifferentAlias123/viewform';assert.throws(()=>h.ctx.formsEvaluationResolve_(h.ctx.formsEvaluationLink_('https://docs.google.com/forms/d/e/DifferentAlias123/viewform'),{}),/não corresponde/);});
test('perfil VERIFIED único e aprovado é a única fonte de UID',()=>{const h=harness(),m=metadata(),r=h.response({uid:'forged-browser-uid'});assert.equal(h.ctx.formsEvaluationResolveIdentity_(m,r,[profile('person')]).uid,'person');assert.equal(h.ctx.formsEvaluationResolveIdentity_(m,r,[profile('person'),profile('second',{email:'person@example.invalid'})]).status,'NEEDS_REVIEW');assert.equal(h.ctx.formsEvaluationResolveIdentity_(m,r,[profile('person',{active:false})]).status,'NEEDS_REVIEW');m.settings.emailCollectionType='RESPONDER_INPUT';assert.equal(h.ctx.formsEvaluationResolveIdentity_(m,r,[profile('person')]).status,'NEEDS_REVIEW');});
test('native zero obrigatório em ciência, sugestão e revisão',()=>{const h=harness();const m=metadata();m.items[0].questionItem.question.grading.pointValue=1;assert.throws(()=>h.ctx.formsEvaluationConfiguration_(m,{modalities:{acknowledgement:true}}),/zero/);});
test('teste exige quiz, escolha real, gabarito e pesos confirmados',()=>{const h=harness();for(const mutate of [m=>m.settings.quizSettings.isQuiz=false,m=>delete m.items[4].questionItem.question.grading.correctAnswers,m=>m.items[4].questionItem.question.grading.correctAnswers.answers=[{value:'C'}],m=>m.items[4].questionItem.question.grading.pointValue=1.5]){const m=metadata();mutate(m);assert.throws(()=>h.ctx.formsEvaluationConfiguration_(m,{modalities:{test:true}}));}assert.equal(h.ctx.formsEvaluationConfiguration_(metadata(),{modalities:{test:true}}).maxTestScore,5);});
test('renomear formulário ou copiar IDs não é alteração efetiva dos testes',()=>{const h=harness(),a=metadata(),b=metadata();b.info.title='Título administrativo novo';b.items.forEach(i=>{i.itemId+='copy';i.questionItem.question.questionId+='copy';});assert.equal(h.ctx.formsEvaluationConfiguration_(a,{modalities:{test:true}}).questionFingerprint,h.ctx.formsEvaluationConfiguration_(b,{modalities:{test:true}}).questionFingerprint);b.items[4].title='Questão realmente alterada';assert.notEqual(h.ctx.formsEvaluationConfiguration_(a,{modalities:{test:true}}).questionFingerprint,h.ctx.formsEvaluationConfiguration_(b,{modalities:{test:true}}).questionFingerprint);});
test('ciência SIM concede1 e nota Forms efetiva concede peso real; reprocessamento não duplica',()=>{const h=harness();h.seedFixture();h.configuration();setResponse(h,h.response());h.ctx.formsEvaluationProcessResponse_(FORM,'response-fixture');assert.equal(h.values('evaluationAwards').find(a=>a.modality==='ACKNOWLEDGEMENT').points,1);assert.equal(h.values('evaluationAwards').find(a=>a.modality==='TEST').points,5);assert.equal(h.awards.find(a=>a.modality==='TEST').maxTestScore,5);const initial=h.values('evaluationLedger').length;h.ctx.formsEvaluationProcessResponse_(FORM,'response-fixture');assert.equal(h.values('evaluationLedger').length,initial);});
test('nota ausente fica pendente sem zero inventado, mas ciência continua independente',()=>{const h=harness();h.seedFixture();h.configuration();const r=h.response();delete r.totalScore;setResponse(h,r);const result=h.ctx.formsEvaluationProcessResponse_(FORM,r.responseId);assert.equal(result.status,'PENDING');assert.equal(h.values('evaluationAwards').length,1);assert.equal(h.values('evaluationParticipations')[0].test.status,'PENDING_GRADE');});
test('nota zero real é preservada e nota acima do máximo não concede pontos',()=>{const h=harness();const m=h.seedFixture(),cfg=h.configuration();assert.equal(h.ctx.formsEvaluationParticipation_(m,cfg,h.response({totalScore:0}),[profile('person')]).test.score,0);assert.equal(h.ctx.formsEvaluationParticipation_(m,cfg,h.response({totalScore:6}),[profile('person')]).status,'NEEDS_REVIEW');});
test('resposta fora do público/vigência e formulário alterado ficam NEEDS_REVIEW',()=>{const h=harness(),m=h.seedFixture(),cfg=h.configuration();assert.equal(h.ctx.formsEvaluationParticipation_(m,{...cfg,eligibleUids:[]},h.response(),[profile('person')]).status,'NEEDS_REVIEW');assert.equal(h.ctx.formsEvaluationParticipation_(m,cfg,h.response({createTime:'2025-01-01'}),[profile('person')]).status,'NEEDS_REVIEW');m.items[4].questionItem.question.grading.pointValue=4;assert.equal(h.ctx.formsEvaluationParticipation_(m,cfg,h.response(),[profile('person')]).status,'NEEDS_REVIEW');});
test('segundo Forms da mesma matéria/versão não duplica participação',()=>{const h=harness();h.seedFixture();h.configuration();setResponse(h,h.response());h.ctx.formsEvaluationProcessResponse_(FORM,'response-fixture');const participation=h.values('evaluationParticipations')[0];h.seed('evaluationParticipations',participation.id,{...participation,activityId:'AnotherForm12345',responseId:'other-response'});const count=h.values('evaluationLedger').length;assert.equal(h.ctx.formsEvaluationProcessResponse_(FORM,'response-fixture').status,'NEEDS_REVIEW');assert.equal(h.values('evaluationLedger').length,count);});
test('correção administrativa divergente nunca é restaurada pela nota Forms',()=>{const h=harness();h.seedFixture();h.configuration();setResponse(h,h.response());h.ctx.formsEvaluationProcessResponse_(FORM,'response-fixture');const a=h.values('evaluationAwards').find(a=>a.modality==='TEST');h.seed('evaluationAwards',a.id,{...a,points:3,adminOverride:true});const before=h.values('evaluationLedger').length;assert.equal(h.ctx.formsEvaluationProcessResponse_(FORM,'response-fixture').status,'NEEDS_REVIEW');assert.equal(h.get('evaluationAwards',a.id).points,3);assert.equal(h.values('evaluationLedger').length,before);});
test('sugestão pertinente só recebe2 após revisão independente; reprocessar preserva decisão',()=>{const h=harness();h.seedFixture();h.configuration();const r=setResponse(h,h.response({answers:{ack:answer('SIM'),problem:answer('Problema relevante fictício'),proposal:answer('Proposta original pertinente'),benefit:answer('Benefício esperado relevante')}}));h.ctx.formsEvaluationProcessResponse_(FORM,r.responseId);const p=h.values('evaluationParticipations')[0];assert.equal(p.suggestion.status,'PENDING');assert.throws(()=>run(h,'formsEvaluationReviewSuggestion_',{participationId:p.id,decision:'APPROVE',note:'Análise independente'},'person'),/autoaprovação/);run(h,'formsEvaluationReviewSuggestion_',{participationId:p.id,decision:'APPROVE',note:'Sugestão pertinente e original'},'manager');assert.equal(h.values('evaluationAwards').find(a=>a.modality==='SUGGESTION').points,2);h.ctx.formsEvaluationProcessResponse_(FORM,r.responseId);assert.equal(h.values('evaluationParticipations')[0].suggestion.status,'APPROVED');assert.notEqual(h.values('evaluationParticipations')[0].status,'NEEDS_REVIEW');});
test('sugestão vazia, repetitiva ou revisor alheio não pontua',()=>{const h=harness(),m=h.seedFixture(),cfg=h.configuration();const d=h.ctx.formsEvaluationParticipation_(m,cfg,h.response({answers:{problem:answer('mesma resposta'),proposal:answer('mesma resposta'),benefit:answer('mesma resposta')}}),[profile('person')]);assert.equal(d.suggestion.status,'INVALID');h.seed('evaluationParticipations','part',{uid:'person',activityId:FORM,suggestion:{problem:'Problema válido',proposal:'Proposta válida',benefit:'Benefício válido',status:'PENDING'}});h.seed('users','outsider',profile('outsider'));assert.throws(()=>run(h,'formsEvaluationReviewSuggestion_',{participationId:'part',decision:'APPROVE',note:'Revisão pertinente'},'outsider'),/não autorizado/);});
test('designação possui CAS/histórico imutável e preserva permissões/arrays legados',()=>{const h=harness();h.seedFixture();run(h,'formsEvaluationAssignments_',{areaId:AREA,managerUid:'person',expectedVersion:1});assert.equal(h.get('evaluationAssignments',AREA).version,2);assert.equal(h.values('evaluationAssignmentHistory').length,2);assert.deepEqual(h.get('managementAreas',AREA).managerUids,['preserved-legacy']);assert.deepEqual(h.get('users','person').permissions,{});assert.throws(()=>run(h,'formsEvaluationAssignments_',{areaId:AREA,managerUid:'manager',expectedVersion:1}),/mudou/);});
test('designar gestor exige administrador, área ativa e perfil aprovado',()=>{const h=harness();h.seedFixture();assert.throws(()=>run(h,'formsEvaluationAssignments_',{areaId:AREA,managerUid:'person',expectedVersion:1},'person'),/administrador/);h.seed('users','person',profile('person',{access:false}));assert.throws(()=>run(h,'formsEvaluationAssignments_',{areaId:AREA,managerUid:'person',expectedVersion:1}),/vigente/);});
test('configuração de hoje aceita calendário local e impede importar respostas anteriores',()=>{const h=harness();h.seedFixture();const day=h.ctx.Utilities.formatDate(new Date());const result=run(h,'formsEvaluationConfigured_',{activityId:FORM,creditScopeId:'matter',version:1,expectedVersion:0,eligibleUids:['person'],managerAreaId:AREA,validFrom:day,validUntil:'2099-12-31',modalities:{test:true}});assert.equal(result.configVersion,1);const cfg=h.get('evaluationFormConfigs',FORM);assert.ok(cfg.firstEligibleAt>=new Date(Date.now()-10000));assert.equal(cfg.validUntil.getUTCHours(),2);assert.ok(h.queries.some(q=>q.c==='evaluationFormConfigs'&&q.tx==='mock-transaction'));assert.throws(()=>run(h,'formsEvaluationConfigured_',{activityId:FORM,creditScopeId:'matter',version:1,expectedVersion:0,eligibleUids:['person'],managerAreaId:AREA,validFrom:day,validUntil:'2099-12-31',modalities:{test:true}}),/mudou/);});
test('cópia administrativa/novo título não autoriza nova versão; original protegido não configura',()=>{const h=harness();h.seedFixture();h.configuration();const payload={activityId:FORM,creditScopeId:'matter',version:2,expectedVersion:1,eligibleUids:['person'],managerAreaId:AREA,validFrom:'2026-01-01',validUntil:'2099-12-31',modalities:{acknowledgement:true,suggestion:true,test:true}};assert.throws(()=>run(h,'formsEvaluationConfigured_',payload),/alteração efetiva/);h.props.set('SAHMT_V2_EVALUATION_PROTECTED_FORM_IDS',FORM);assert.throws(()=>run(h,'formsEvaluationConfigured_',payload),/protegido/);});
test('configuração incompleta/não publicada é pendência explícita',()=>{const h=harness();h.seedFixture();h.forms.get(FORM).isPublished=()=>false;const day=h.ctx.Utilities.formatDate(new Date());const result=run(h,'formsEvaluationConfigured_',{activityId:FORM,creditScopeId:'matter',version:1,expectedVersion:0,eligibleUids:['person'],managerAreaId:AREA,validFrom:day,validUntil:'2099-12-31',modalities:{test:true}});assert.equal(result.status,'CONFIGURATION_PENDING');assert.equal(h.values('evaluationAwards').length,0);});
test('governança de questões exige mudança efetiva, designação e administrador independente',()=>{const h=harness();changedQuestions(h);const requested=run(h,'formsEvaluationGovernanceRequest_',govPayload(),'manager');assert.equal(requested.status,'PENDING');assert.throws(()=>run(h,'formsEvaluationReviewGovernance_',{revisionId:requested.revisionId,decision:'APPROVE',note:'Conferência independente'},'manager'),/administrador distinto/);run(h,'formsEvaluationReviewGovernance_',{revisionId:requested.revisionId,decision:'APPROVE',note:'Questão e gabarito conferidos'},'admin');const awards=h.values('evaluationAwards');assert.equal(awards.length,1);assert.equal(awards[0].category,'GOVERNANCE');assert.equal(awards[0].points,1);assert.equal(run(h,'formsEvaluationGovernanceRequest_',govPayload(),'manager').duplicate,true);});
test('baseline ausente/renomeação não concede governança',()=>{const h=harness();h.seedFixture();h.configuration();h.google.set(`https://www.googleapis.com/drive/v3/files/${FORM}?fields=id,modifiedTime,lastModifyingUser(emailAddress)`,{id:FORM,modifiedTime:new Date().toISOString(),lastModifyingUser:{emailAddress:'manager@example.invalid'}});const pending=run(h,'formsEvaluationGovernanceRequest_',govPayload(),'manager');assert.equal(pending.status,'NEEDS_REVIEW');assert.throws(()=>run(h,'formsEvaluationReviewGovernance_',{revisionId:pending.revisionId,decision:'APPROVE',note:'Conferência manual com evidências insuficientes'}),/snapshots/);assert.equal(h.values('evaluationAwards').length,0);});
