test('questão pontuada continua no fingerprint mesmo com prefixo SAHMT e mudança de gabarito é detectada',()=>{const h=harness(),meta=metadata();meta.items[4].title='[SAHMT:TEST] Questão real';const before=h.ctx.formsEvaluationConfiguration_(meta,{modalities:{test:true}}).questionFingerprint;meta.items[4].questionItem.question.grading.correctAnswers.answers=[{value:'B'}];assert.notEqual(h.ctx.formsEvaluationConfiguration_(meta,{modalities:{test:true}}).questionFingerprint,before);});
test('troca e retorno de gestor com renomeação não duplicam componente/conteúdo já aprovado',()=>{const h=harness(),meta=changedQuestions(h);const first=run(h,'formsEvaluationGovernanceRequest_',govPayload(),'manager');run(h,'formsEvaluationReviewGovernance_',{revisionId:first.revisionId,decision:'APPROVE',note:'Questões conferidas originalmente'});run(h,'formsEvaluationAssignments_',{areaId:AREA,managerUid:'person',expectedVersion:1});run(h,'formsEvaluationAssignments_',{areaId:AREA,managerUid:'manager',expectedVersion:2});meta.info.title='Título novo, conteúdo igual';h.google.set(`https://forms.googleapis.com/v1/forms/${FORM}`,meta);h.google.set(`https://www.googleapis.com/drive/v3/files/${FORM}?fields=id,modifiedTime,lastModifyingUser(emailAddress)`,{id:FORM,modifiedTime:new Date(Date.now()+1000).toISOString(),lastModifyingUser:{emailAddress:'manager@example.invalid'}});const repeat=run(h,'formsEvaluationGovernanceRequest_',govPayload(),'manager');assert.equal(repeat.status,'NEEDS_REVIEW');assert.match(h.get('evaluationGovernanceRevisions',repeat.revisionId).reason,/já foi aprovado/);assert.equal(run(h,'formsEvaluationReviewGovernance_',{revisionId:repeat.revisionId,decision:'APPROVE',note:'Tentativa conferida independentemente'}).status,'NEEDS_REVIEW');assert.equal(h.values('evaluationAwards').length,1);assert.equal(h.get('evaluationGovernanceRevisions',first.revisionId).approvedByUid,'admin');});
test('alteração efetiva diferente na nova designação permanece elegível, sem transferir crédito anterior',()=>{const h=harness(),meta=changedQuestions(h);const first=run(h,'formsEvaluationGovernanceRequest_',govPayload(),'manager');run(h,'formsEvaluationReviewGovernance_',{revisionId:first.revisionId,decision:'APPROVE',note:'Questões originais conferidas'});run(h,'formsEvaluationAssignments_',{areaId:AREA,managerUid:'person',expectedVersion:1});meta.items[4].title='Nova pergunta efetivamente criada pelo outro gestor';h.google.set(`https://forms.googleapis.com/v1/forms/${FORM}`,meta);h.google.set(`https://www.googleapis.com/drive/v3/files/${FORM}?fields=id,modifiedTime,lastModifyingUser(emailAddress)`,{id:FORM,modifiedTime:new Date(Date.now()+1000).toISOString(),lastModifyingUser:{emailAddress:'person@example.invalid'}});const second=run(h,'formsEvaluationGovernanceRequest_',govPayload({newVersion:3}),'person');assert.equal(second.status,'PENDING');run(h,'formsEvaluationReviewGovernance_',{revisionId:second.revisionId,decision:'APPROVE',note:'Nova alteração efetiva conferida'});assert.equal(h.values('evaluationAwards').find(a=>a.uid==='manager').points,1);assert.equal(h.values('evaluationAwards').find(a=>a.uid==='person').points,1);});
test('material substituído por novo arquivo com conteúdo novo é elegível; cópia de conteúdo idêntico não é',()=>{for(const changed of [true,false]){const h=harness();changedQuestions(h);materialFixture(h);const cfg=h.get('evaluationFormConfigs',FORM),file='ReplacementFixture123456',url=`https://drive.google.com/file/d/${file}/view`;cfg.materialUrls=[url];h.seed('evaluationFormConfigs',FORM,cfg);h.google.set(`https://www.googleapis.com/drive/v3/files/${file}?fields=id,mimeType,modifiedTime,md5Checksum,description,lastModifyingUser(emailAddress),shortcutDetails(targetId,targetMimeType)`,{id:file,mimeType:'application/pdf',md5Checksum:changed?'actually-new-content':'old-content-hash',modifiedTime:new Date().toISOString(),lastModifyingUser:{emailAddress:'manager@example.invalid'}});const request=run(h,'formsEvaluationGovernanceRequest_',govPayload({components:['MATERIAL'],materialEvidence:[url],questionEvidence:[]}),'manager');assert.equal(request.status,changed?'PENDING':'NEEDS_REVIEW');if(changed){run(h,'formsEvaluationReviewGovernance_',{revisionId:request.revisionId,decision:'APPROVE',note:'PDF novo e conteúdo conferidos'});assert.equal(h.values('evaluationAwards')[0].points,1);}else assert.equal(h.values('evaluationAwards').length,0);}});
test('fingerprints de materiais ignoram ordem, URL duplicada e arquivo copiado com hash idêntico',()=>{const h=harness(),first=[{fileId:'one',url:'https://drive.google.com/file/d/FileOne123456/view',contentHash:'A'},{fileId:'two',contentHash:'B'}],reordered=[first[1],first[0],{...first[0],fileId:'copied',url:'https://drive.google.com/file/d/CopiedFile123456/view'}];assert.equal(h.ctx.formsEvaluationMaterialFingerprint_(first),h.ctx.formsEvaluationMaterialFingerprint_(reordered));assert.notEqual(h.ctx.formsEvaluationMaterialFingerprint_(first),h.ctx.formsEvaluationMaterialFingerprint_([{contentHash:'C'}]));});

test('reordenar ou duplicar URLs de materiais não autoriza nova versão elegível na configuração real',()=>{const h=harness();h.seedFixture();h.configuration();const first='MaterialA123456789',second='MaterialB123456789',url=id=>`https://drive.google.com/file/d/${id}/view`;for(const [id,hash]of [[first,'A'],[second,'B']])h.google.set(`https://www.googleapis.com/drive/v3/files/${id}?fields=id,mimeType,modifiedTime,md5Checksum,description,lastModifyingUser(emailAddress),shortcutDetails(targetId,targetMimeType)`,{id,mimeType:'application/pdf',md5Checksum:hash});const cfg=h.get('evaluationFormConfigs',FORM);cfg.materialUrls=[url(first),url(second)];cfg.materialSnapshot=[{fileId:first,contentHash:'A'},{fileId:second,contentHash:'B'}];cfg.materialFingerprint=h.ctx.formsEvaluationMaterialFingerprint_(cfg.materialSnapshot);h.seed('evaluationFormConfigs',FORM,cfg);assert.throws(()=>run(h,'formsEvaluationConfigured_',{activityId:FORM,creditScopeId:'matter',version:2,expectedVersion:1,eligibleUids:['person'],managerAreaId:AREA,validFrom:'2026-01-01',validUntil:'2099-12-31',modalities:{acknowledgement:true,suggestion:true,test:true},materialUrls:[url(second),url(first),url(first)]}),/alteração efetiva/);assert.equal(h.get('evaluationFormConfigs',FORM).version,1);});
test('aprovação revalida deduplicação se outro gestor teve o mesmo componente aprovado depois do pedido',()=>{const h=harness();changedQuestions(h);const first=run(h,'formsEvaluationGovernanceRequest_',govPayload(),'manager');run(h,'formsEvaluationAssignments_',{areaId:AREA,managerUid:'person',expectedVersion:1});h.google.set(`https://www.googleapis.com/drive/v3/files/${FORM}?fields=id,modifiedTime,lastModifyingUser(emailAddress)`,{id:FORM,modifiedTime:new Date(Date.now()+1000).toISOString(),lastModifyingUser:{emailAddress:'person@example.invalid'}});const second=run(h,'formsEvaluationGovernanceRequest_',govPayload(),'person');assert.equal(second.status,'PENDING');run(h,'formsEvaluationReviewGovernance_',{revisionId:first.revisionId,decision:'APPROVE',note:'Componente do primeiro gestor conferido'});assert.equal(run(h,'formsEvaluationReviewGovernance_',{revisionId:second.revisionId,decision:'APPROVE',note:'Revisão independente da duplicidade'}).status,'NEEDS_REVIEW');assert.equal(h.values('evaluationAwards').length,1);});

test('mudar apenas newVersion de2 para3 sem mudança de conteúdo não repete governança',()=>{const h=harness();changedQuestions(h);const first=run(h,'formsEvaluationGovernanceRequest_',govPayload(),'manager');run(h,'formsEvaluationReviewGovernance_',{revisionId:first.revisionId,decision:'APPROVE',note:'Questões originais conferidas'});const second=run(h,'formsEvaluationGovernanceRequest_',govPayload({newVersion:3}),'manager');assert.equal(second.status,'NEEDS_REVIEW');assert.equal(run(h,'formsEvaluationReviewGovernance_',{revisionId:second.revisionId,decision:'APPROVE',note:'Número de versão conferido sem nova alteração'}).status,'NEEDS_REVIEW');assert.equal(h.values('evaluationAwards').length,1);assert.equal(h.values('evaluationAwards')[0].points,1);});
test('cópia em outra área/gestor com mesmas questões reais não repete o componente aprovado da matéria',()=>{const h=harness(),meta=changedQuestions(h),originalCfg=h.get('evaluationFormConfigs',FORM);const first=run(h,'formsEvaluationGovernanceRequest_',govPayload(),'manager');run(h,'formsEvaluationReviewGovernance_',{revisionId:first.revisionId,decision:'APPROVE',note:'Questões e autoria originais conferidas'});const copy='CopiedFormFixture123456',otherArea='other-area',copied=clone(meta);copied.formId=copy;copied.responderUri='https://docs.google.com/forms/d/e/CopiedPublicAlias123456/viewform';copied.info.title='Cópia renomeada';for(const item of copied.items){item.itemId+='copy';item.questionItem.question.questionId+='copy';}h.google.set(`https://forms.googleapis.com/v1/forms/${copy}`,copied);h.google.set(`https://www.googleapis.com/drive/v3/files/${copy}?fields=id,modifiedTime,lastModifyingUser(emailAddress)`,{id:copy,modifiedTime:new Date().toISOString(),lastModifyingUser:{emailAddress:'person@example.invalid'}});h.seed('managementAreas',otherArea,{active:true});h.seed('evaluationAssignments',otherArea,{uid:'person',areaId:otherArea,version:1,effectiveAt:new Date('2026-01-01')});h.seed('evaluationAssignmentHistory',`assignment-${h.ctx.formsEvaluationHash_(`${otherArea}\0${1}`)}`,{uid:'person',areaId:otherArea,version:1,effectiveAt:new Date('2026-01-01')});h.seed('evaluationFormConfigs',copy,{...originalCfg,formId:copy,responderUrl:copied.responderUri,managerAreaId:otherArea,managerUid:'person',assignmentId:otherArea});const second=run(h,'formsEvaluationGovernanceRequest_',govPayload({activityId:copy,areaId:otherArea,assignmentId:otherArea,newVersion:3,questionEvidence:[`https://docs.google.com/forms/d/${copy}/edit`]}),'person');assert.equal(second.status,'NEEDS_REVIEW');assert.equal(run(h,'formsEvaluationReviewGovernance_',{revisionId:second.revisionId,decision:'APPROVE',note:'Cópia conferida sem mudança real nas questões'}).status,'NEEDS_REVIEW');assert.equal(h.values('evaluationAwards').length,1);assert.equal(h.values('evaluationAwards')[0].uid,'manager');});
function nativeDocFixture(suffix='original',uri='https://images.invalid/token-original',withImage=true,text='Conteúdo real de referência\n'){
  const inline=`image-${suffix}`,header=`header-${suffix}`,footnote=`footnote-${suffix}`,list=`list-${suffix}`;
  return{documentId:`doc-${suffix}`,title:`Título ${suffix}`,body:{content:[{paragraph:{bullet:{listId:list,nestingLevel:0},elements:[{textRun:{content:text}},{footnoteReference:{footnoteId:footnote}},...(withImage?[{inlineObjectElement:{inlineObjectId:inline}}]:[])]}}]},documentStyle:{defaultHeaderId:header},headers:{[header]:{headerId:header,content:[{paragraph:{elements:[{textRun:{content:'Cabeçalho textual\n'}}]}}]}},footnotes:{[footnote]:{footnoteId:footnote,content:[{paragraph:{elements:[{textRun:{content:'Nota textual importante\n'}}]}}]}},lists:{[list]:{listId:list,listProperties:{nestingLevels:[{glyphFormat:'%0.',startNumber:1}]}}},...(withImage?{inlineObjects:{[inline]:{objectId:inline,inlineObjectProperties:{embeddedObject:{imageProperties:{contentUri:uri,sourceUri:`https://images.invalid/insertion-${suffix}`}}}}}}:{})};
}
function seedNativeMaterial(h,{type='document',image=true,text='Conteúdo real de referência\n',suffix='original',uri='https://images.invalid/token-original'}={}){
  const file='NativeMaterialFixture123456',url=`https://drive.google.com/file/d/${file}/view`,mime=`application/vnd.google-apps.${type}`;
  const content=type==='document'?nativeDocFixture(suffix,uri,image,text):{presentationId:`presentation-${suffix}`,slides:[{objectId:`slide-${suffix}`,slideProperties:{layoutObjectId:`layout-${suffix}`,masterObjectId:`master-${suffix}`,notesPage:{objectId:`notes-${suffix}`,notesProperties:{speakerNotesObjectId:`text-${suffix}`}}},pageElements:[{objectId:`text-${suffix}`,shape:{text:{textElements:[{textRun:{content:text}}]}}},...(image?[{objectId:`image-${suffix}`,image:{contentUrl:uri,sourceUrl:`https://images.invalid/source-${suffix}`}}]:[])]}],layouts:[{objectId:`layout-${suffix}`}],masters:[{objectId:`master-${suffix}`} ]};
  h.google.set(`https://www.googleapis.com/drive/v3/files/${file}?fields=id,mimeType,modifiedTime,md5Checksum,description,lastModifyingUser(emailAddress),shortcutDetails(targetId,targetMimeType)`,{id:file,mimeType:mime,modifiedTime:new Date().toISOString(),lastModifyingUser:{emailAddress:'manager@example.invalid'}});
  h.google.set(type==='document'?`https://docs.googleapis.com/v1/documents/${file}?includeTabsContent=true`:`https://slides.googleapis.com/v1/presentations/${file}`,content);
  return{file,url,mime,content};
}
function baselineNativeMaterial(h,options={}){const material=seedNativeMaterial(h,options),cfg=h.get('evaluationFormConfigs',FORM);cfg.materialUrls=[material.url];cfg.materialSnapshot=plain(h.ctx.formsEvaluationMaterialSnapshot_([material.url]));cfg.materialFingerprint=h.ctx.formsEvaluationMaterialFingerprint_(cfg.materialSnapshot);h.seed('evaluationFormConfigs',FORM,cfg);return material;}
test('Docs copiados com IDs, mapas e URI temporária diferentes mantêm fingerprint e preservam texto real',()=>{const h=harness(),one={metadata:{mimeType:'application/vnd.google-apps.document'},content:nativeDocFixture()},copy={metadata:{mimeType:'application/vnd.google-apps.document'},content:nativeDocFixture('copy','https://images.invalid/new-token')};const before=h.ctx.formsEvaluationHash_(h.ctx.formsEvaluationContent_(one));assert.equal(before,h.ctx.formsEvaluationHash_(h.ctx.formsEvaluationContent_(copy)));copy.content.footnotes['footnote-copy'].content[0].paragraph.elements[0].textRun.content='Nota alterada de verdade';assert.notEqual(before,h.ctx.formsEvaluationHash_(h.ctx.formsEvaluationContent_(copy)));});
test('Slides imagem com contentUrl renovado e objeto/layout copiado não altera fingerprint',()=>{const h=harness(),first=seedNativeMaterial(h,{type:'presentation',image:true}),second=seedNativeMaterial(h,{type:'presentation',image:true,suffix:'copy',uri:'https://images.invalid/token-renewed'});assert.equal(h.ctx.formsEvaluationHash_(h.ctx.formsEvaluationContent_({metadata:{mimeType:first.mime},content:first.content})),h.ctx.formsEvaluationHash_(h.ctx.formsEvaluationContent_({metadata:{mimeType:second.mime},content:second.content})));});
test('snapshot de imagem/desenho/gráfico nativo é NEEDS_REVIEW explícito e não afirma bytes verificados',()=>{const h=harness();for(const type of ['document','presentation']){const material=seedNativeMaterial(h,{type,image:true});const snapshot=h.ctx.formsEvaluationMaterialSnapshot_([material.url])[0];assert.equal(snapshot.contentVerified,false);assert.equal(snapshot.verificationStatus,'NEEDS_REVIEW');assert.match(snapshot.verificationReason,/bytes estáveis verificáveis/);assert.equal(snapshot.contentHashFormat,'NATIVE_SEMANTIC_V2');}assert.equal(h.values('evaluationAwards').length,0);});
test('trocar só URI de imagem Doc ou Slides não concede MATERIAL e aprovação humana não presume bytes',()=>{for(const type of ['document','presentation']){const h=harness();changedQuestions(h);const material=baselineNativeMaterial(h,{type,image:true});seedNativeMaterial(h,{type,image:true,suffix:'copy',uri:'https://images.invalid/token-renewed'});const request=run(h,'formsEvaluationGovernanceRequest_',govPayload({components:['MATERIAL'],materialEvidence:[material.url],questionEvidence:[]}),'manager');assert.equal(request.status,'NEEDS_REVIEW');assert.match(h.get('evaluationGovernanceRevisions',request.revisionId).reason,/sem bytes estáveis/);assert.throws(()=>run(h,'formsEvaluationReviewGovernance_',{revisionId:request.revisionId,decision:'APPROVE',note:'Conferência humana sem checksum da imagem'}),/bytes estáveis/);assert.equal(h.values('evaluationAwards').length,0);}});
test('QUESTIONS reais continuam independentes quando a matéria nativa contém imagem não verificável',()=>{const h=harness();changedQuestions(h);baselineNativeMaterial(h,{image:true});const request=run(h,'formsEvaluationGovernanceRequest_',govPayload(),'manager');assert.equal(request.status,'PENDING');run(h,'formsEvaluationReviewGovernance_',{revisionId:request.revisionId,decision:'APPROVE',note:'Mudança textual e gabarito conferidos'});assert.equal(h.values('evaluationAwards').length,1);assert.equal(h.values('evaluationAwards')[0].modality,'QUESTIONS');});
test('Docs e Slides textuais verificam alteração real e não pontuam cópia de IDs',()=>{for(const type of ['document','presentation']){const h=harness();changedQuestions(h);const material=baselineNativeMaterial(h,{type,image:false});seedNativeMaterial(h,{type,image:false,suffix:'copy'});const copied=run(h,'formsEvaluationGovernanceRequest_',govPayload({components:['MATERIAL'],materialEvidence:[material.url],questionEvidence:[]}),'manager');assert.equal(copied.status,'NEEDS_REVIEW');seedNativeMaterial(h,{type,image:false,suffix:'copy',text:'Conteúdo de referência realmente atualizado\n'});const changed=run(h,'formsEvaluationGovernanceRequest_',govPayload({components:['MATERIAL'],materialEvidence:[material.url],questionEvidence:[],newVersion:3}),'manager');assert.equal(changed.status,'PENDING');run(h,'formsEvaluationReviewGovernance_',{revisionId:changed.revisionId,decision:'APPROVE',note:'Texto nativo realmente alterado e conferido'});assert.equal(h.values('evaluationAwards').length,1);assert.equal(h.values('evaluationAwards')[0].modality,'MATERIAL');}});
test('imagem renovada/redimensionada isoladamente não torna nova configuração elegível',()=>{const h=harness();const meta=h.seedFixture();h.configuration(meta);baselineNativeMaterial(h,{image:true});const material=seedNativeMaterial(h,{image:true,suffix:'copy',uri:'https://images.invalid/new-token'});material.content.inlineObjects['image-copy'].inlineObjectProperties.embeddedObject.size={width:{magnitude:400,unit:'PT'}};const cfg=h.get('evaluationFormConfigs',FORM);assert.throws(()=>run(h,'formsEvaluationConfigured_',{activityId:FORM,creditScopeId:'matter',version:2,expectedVersion:cfg.configVersion,eligibleUids:['person'],managerAreaId:AREA,validFrom:'2026-01-01',validUntil:'2099-12-31',modalities:{acknowledgement:true,suggestion:true,test:true},materialUrls:[material.url]}),/alteração efetiva/);});
test('baseline nativo legado com hash de IDs/URI não é convertido em crédito pela nova normalização',()=>{const h=harness();changedQuestions(h);const material=baselineNativeMaterial(h,{image:false});const cfg=h.get('evaluationFormConfigs',FORM);cfg.materialSnapshot=[{fileId:material.file,url:material.url,contentHash:'a'.repeat(64)}];cfg.materialFingerprint=h.ctx.formsEvaluationMaterialFingerprint_(cfg.materialSnapshot);h.seed('evaluationFormConfigs',FORM,cfg);const request=run(h,'formsEvaluationGovernanceRequest_',govPayload({components:['MATERIAL'],materialEvidence:[material.url],questionEvidence:[]}),'manager');assert.equal(request.status,'NEEDS_REVIEW');assert.equal(h.values('evaluationAwards').length,0);});
test('Forms Image contentUri/sourceUri/IDs renovados não alteram questões nem nova elegibilidade',()=>{const h=harness();const meta=h.seedFixture();meta.items[4].questionItem.image={contentUri:'https://images.invalid/old',sourceUri:'https://images.invalid/origin-old',altText:'Imagem fictícia',properties:{width:200}};meta.items[4].questionItem.question.choiceQuestion.options[0].image={contentUri:'https://images.invalid/option-old'};h.configuration(meta);const before=h.ctx.formsEvaluationQuestionFingerprint_(h.ctx.formsEvaluationQuestionSnapshot_(meta));meta.items[4].itemId='item-test-copy';meta.items[4].questionItem.question.questionId='test-copy';meta.items[4].questionItem.image={contentUri:'https://images.invalid/renewed',sourceUri:'https://images.invalid/copy',altText:'Nova descrição só da imagem',properties:{width:400}};meta.items[4].questionItem.question.choiceQuestion.options[0].image.contentUri='https://images.invalid/option-renewed';h.google.set(`https://www.googleapis.com/drive/v3/files/${FORM}?fields=id,modifiedTime,lastModifyingUser(emailAddress)`,{id:FORM,modifiedTime:new Date().toISOString(),lastModifyingUser:{emailAddress:'manager@example.invalid'}});assert.equal(h.ctx.formsEvaluationQuestionFingerprint_(h.ctx.formsEvaluationQuestionSnapshot_(meta)),before);const request=run(h,'formsEvaluationGovernanceRequest_',govPayload(),'manager');assert.equal(request.status,'NEEDS_REVIEW');assert.equal(h.values('evaluationAwards').length,0);assert.throws(()=>run(h,'formsEvaluationConfigured_',{activityId:FORM,creditScopeId:'matter',version:2,expectedVersion:1,eligibleUids:['person'],managerAreaId:AREA,validFrom:'2026-01-01',validUntil:'2099-12-31',modalities:{acknowledgement:true,suggestion:true,test:true}}),/alteração efetiva/);});
test('título, alternativas, gabarito e peso das questões seguem verificáveis mesmo com imagens temporárias',()=>{const h=harness(),original=metadata();original.items[4].questionItem.image={contentUri:'https://images.invalid/old'};const before=h.ctx.formsEvaluationQuestionFingerprint_(h.ctx.formsEvaluationQuestionSnapshot_(original));for(const change of [m=>m.items[4].title='Questão textual realmente atualizada',m=>m.items[4].questionItem.question.choiceQuestion.options[1].value='Alternativa C',m=>m.items[4].questionItem.question.grading.correctAnswers.answers[0].value='B',m=>m.items[4].questionItem.question.grading.pointValue=10]){const changed=clone(original);change(changed);changed.items[4].questionItem.image.contentUri='https://images.invalid/renewed';assert.notEqual(h.ctx.formsEvaluationQuestionFingerprint_(h.ctx.formsEvaluationQuestionSnapshot_(changed)),before);}});
test('questões textuais atualizadas com imagem no Form continuam concedendo só seu componente',()=>{const h=harness(),meta=h.seedFixture();meta.items[4].questionItem.image={contentUri:'https://images.invalid/old'};h.configuration(meta);meta.items[4].title='Questão textual atualizada, sem presumir a imagem';meta.items[4].questionItem.image.contentUri='https://images.invalid/renewed';h.google.set(`https://www.googleapis.com/drive/v3/files/${FORM}?fields=id,modifiedTime,lastModifyingUser(emailAddress)`,{id:FORM,modifiedTime:new Date().toISOString(),lastModifyingUser:{emailAddress:'manager@example.invalid'}});const request=run(h,'formsEvaluationGovernanceRequest_',govPayload(),'manager');assert.equal(request.status,'PENDING');run(h,'formsEvaluationReviewGovernance_',{revisionId:request.revisionId,decision:'APPROVE',note:'Texto e gabarito realmente alterados conferidos'});assert.equal(h.values('evaluationAwards').length,1);assert.equal(h.values('evaluationAwards')[0].modality,'QUESTIONS');});
test('baseline bruto legado de questões é renormalizado e URI renovada não vira alteração ou bloqueio falso',()=>{const h=harness(),meta=h.seedFixture();meta.items[4].questionItem.image={contentUri:'https://images.invalid/old'};const cfg=h.configuration(meta);function legacy(value){if(Array.isArray(value))return value.map(legacy);if(!value||typeof value!=='object')return value;return Object.fromEntries(Object.entries(value).filter(([key])=>!['itemId','questionId','rowQuestionId'].includes(key)).map(([key,v])=>[key,legacy(v)]));}cfg.questionFingerprint=h.ctx.formsEvaluationHash_(cfg.questionSnapshot.filter(item=>!item.title.startsWith('[SAHMT:')).map(legacy));h.seed('evaluationFormConfigs',FORM,cfg);meta.items[4].questionItem.image.contentUri='https://images.invalid/renewed';assert.equal(h.ctx.formsEvaluationParticipation_(meta,h.get('evaluationFormConfigs',FORM),h.response(),[profile('person')]).status,'CONFIRMED');h.google.set(`https://www.googleapis.com/drive/v3/files/${FORM}?fields=id,modifiedTime,lastModifyingUser(emailAddress)`,{id:FORM,modifiedTime:new Date().toISOString(),lastModifyingUser:{emailAddress:'manager@example.invalid'}});assert.equal(run(h,'formsEvaluationGovernanceRequest_',govPayload(),'manager').status,'NEEDS_REVIEW');assert.equal(h.values('evaluationAwards').length,0);});
test('Docs lê todas as abas e copia de tabId não cria hash novo; texto na segunda aba é verificado',()=>{const h=harness();const material=seedNativeMaterial(h,{image:false});const content={documentId:'NativeOriginal',tabs:[{tabProperties:{tabId:'first-original',title:'Primeira'},documentTab:{body:{content:[{paragraph:{elements:[{textRun:{content:'Primeiro texto\n'}}]}}]}}},{tabProperties:{tabId:'second-original',title:'Segunda'},documentTab:{body:{content:[{paragraph:{elements:[{textRun:{content:'Segundo texto real\n'}}]}}]}}}]};h.google.set(`https://docs.googleapis.com/v1/documents/${material.file}?includeTabsContent=true`,content);const before=h.ctx.formsEvaluationMaterialSnapshot_([material.url])[0];const copied=clone(content);copied.documentId='NativeCopy';copied.tabs[0].tabProperties.tabId='first-copy';copied.tabs[1].tabProperties.tabId='second-copy';h.google.set(`https://docs.googleapis.com/v1/documents/${material.file}?includeTabsContent=true`,copied);assert.equal(before.contentHash,h.ctx.formsEvaluationMaterialSnapshot_([material.url])[0].contentHash);copied.tabs[1].documentTab.body.content[0].paragraph.elements[0].textRun.content='Segunda aba efetivamente alterada\n';assert.notEqual(before.contentHash,h.ctx.formsEvaluationMaterialSnapshot_([material.url])[0].contentHash);assert.equal(h.ctx.formsEvaluationMaterialSnapshot_([material.url])[0].contentVerified,true);});
test('headingId dentro de mapa textual copiado não altera conteúdo mas mudança do cabeçalho altera',()=>{const h=harness(),first={metadata:{mimeType:'application/vnd.google-apps.document'},content:nativeDocFixture('first','',false)},copy={metadata:{mimeType:'application/vnd.google-apps.document'},content:nativeDocFixture('second','',false)};first.content.headers['header-first'].content[0].paragraph.paragraphStyle={headingId:'heading-first',namedStyleType:'HEADING_1'};copy.content.headers['header-second'].content[0].paragraph.paragraphStyle={headingId:'heading-second',namedStyleType:'HEADING_1'};assert.equal(h.ctx.formsEvaluationHash_(h.ctx.formsEvaluationContent_(first)),h.ctx.formsEvaluationHash_(h.ctx.formsEvaluationContent_(copy)));copy.content.headers['header-second'].content[0].paragraph.elements[0].textRun.content='Cabeçalho real atualizado\n';assert.notEqual(h.ctx.formsEvaluationHash_(h.ctx.formsEvaluationContent_(first)),h.ctx.formsEvaluationHash_(h.ctx.formsEvaluationContent_(copy)));});

function captureFixture(extra={}) {
  const h=harness(),meta=h.seedFixture();meta.info.title='[HOMOLOGAÇÃO SAHMT] Ensaio fictício';
  const cfg=h.configuration(meta,{eligibleUids:['person','manager','admin'],assignmentVersion:1,...extra});
  h.props.set('SAHMT_V2_EVALUATION_HOMOLOGATION_FORM_ID',FORM);
  const url=`https://forms.googleapis.com/v1/forms/${FORM}/responses?pageSize=25&filter=${encodeURIComponent('timestamp >= '+new Date(Math.max(new Date(cfg.validFrom).getTime(),new Date(cfg.firstEligibleAt).getTime())).toISOString())}`;
  h.google.set(url,{responses:[h.response()]});h.enable(false);
  return{h,meta,cfg,url};
}
function capture(h){return h.ctx.capturarHomologacaoAvaliacaoSahmtV2();}

test('captura privada usa operador sem ativação e salva apenas entrada de homologação com timestamp servidor',()=>{
  const {h}=captureFixture();
  for(const collection of ['evaluationAwards','evaluationLedger','evaluationSummaries','evaluationReferences','evaluationRuntime','scores'])h.seed(collection,'legacy',{sentinel:'must-preserve'});
  for(const key of ['SAHMT_V2_EVALUATION_ENABLED','SAHMT_V2_EVALUATION_HOMOLOGATED'])h.props.set(key,'false');
  const before=clone(Array.from(h.store.entries())),properties=clone(Array.from(h.props.entries()));
  for(const method of ['setAcceptingResponses','setAllowResponseEdits','setLimitOneResponsePerUser','setPublished','deleteAllResponses'])h.forms.get(FORM)[method]=()=>{throw Error('Cannot mutate Forms in capture');};
  const result=capture(h),snapshot=h.get('evaluationHomologationInputs',result.runId);
  assert.equal(result.status,'CAPTURED');assert.equal(result.responses,1);assert.deepEqual(h.operatorChecks,[false]);
  assert.equal(snapshot.schemaVersion,1);assert.equal(snapshot.source,'FORMS_HOMOLOGATION_CAPTURE');assert.equal(snapshot.productionFinancialWrites,false);
  assert.equal(snapshot.purpose,'ISOLATED_EVALUATION_HOMOLOGATION');assert.ok(snapshot.capturedAt instanceof Date);assert.equal(snapshot.operatorUid,'admin');
  assert.deepEqual(snapshot.roles,{participantUid:'person',managerUid:'manager',reviewerUid:'admin'});assert.equal(snapshot.profiles.length,3);
  assert.equal(snapshot.config.id,FORM);assert.equal(snapshot.activity.id,FORM);assert.equal(snapshot.area.id,AREA);assert.equal(snapshot.assignment.id,AREA);assert.equal(snapshot.assignmentHistory.length,1);
  assert.ok(snapshot.profiles.every(p=>!('_updateTime' in p)&&!('_documentName' in p)));
  assert.deepEqual(Array.from(h.store.entries()).filter(([key])=>!key.startsWith('evaluationHomologationInputs/')),before);
  assert.deepEqual(Array.from(h.props.entries()),properties);assert.equal(h.awards.length,0);assert.equal(h.commits.length,1);assert.equal(h.commits[0][0].c,'evaluationHomologationInputs');
  assert.deepEqual(plain(h.commits[0][0].times),['capturedAt']);assert.ok(!JSON.stringify(result).includes('@'));assert.ok(!JSON.stringify(result).includes('answers'));
});
