  const second=h.ctx.processEvaluationRequests();assert.equal(second.processed,1);assert.equal(h.get('evaluationAssignments',AREA).uid,'person');assert.equal(h.get('evaluationRequests','z-later-assignment').status,'CONFIRMED');
  const third=h.ctx.processEvaluationRequests();assert.equal(third.pending,20);assert.equal(h.values('evaluationRequests').filter(r=>r.status==='PENDING').length,20);assert.equal(h.values('evaluationAwards').length,0);
