test('consulta nativa transmite cursor exclusivo createdAt e documento sem alterar assinatura transacional existente',()=>{
  const h=harness();let request;h.ctx.firestoreDocumentsUrl_=suffix=>'local-only'+suffix;h.ctx.firestoreRequest_=(url,options)=>{assert.equal(url,'local-only:runQuery');request=JSON.parse(options.payload);return[];};
  const cursor={values:[{timestampValue:'2026-10-01T12:00:00Z'},{referenceValue:h.ctx.firestoreDocumentName_('evaluationRequests','request-last')}],before:false};
  h.nativeQuery('evaluationRequests',[h.ctx.firestoreFilter_('status','EQUAL',{stringValue:'PENDING'})],[{fieldPath:'createdAt',direction:'ASCENDING'},{fieldPath:'__name__',direction:'ASCENDING'}],20,null,'real-query-transaction',cursor);
  assert.deepEqual(request.structuredQuery.startAt,cursor);assert.equal(request.transaction,'real-query-transaction');assert.equal(request.structuredQuery.limit,20);
});
test('varredura atual de identidades incompleta falha fechada sem permitir pontos com pool antigo',()=>{
  const h=harness();h.seedFixture();h.configuration();setResponse(h,h.response());const pool=h.values('users');h.ctx.formsEvaluationAll_=(collection,filters,tx)=>{assert.equal(collection,'users');assert.equal(tx,'mock-transaction');throw Error('Reconciliação incompleta: limite de leitura alcançado');};
  assert.throws(()=>h.ctx.formsEvaluationProcessResponse_(FORM,'response-fixture',pool),/Reconciliação incompleta/);assert.equal(h.values('evaluationAwards').length,0);assert.equal(h.values('evaluationParticipations').length,0);
});

function googleFailure(h,body,status=403) {
  h.ctx.UrlFetchApp={fetch:(url,options)=>{assert.equal(options.muteHttpExceptions,true);assert.equal(options.headers.Authorization,'Bearer fake-no-live-token');return{getResponseCode:()=>status,getContentText:()=>typeof body==='string'?body:JSON.stringify(body)};}};
  return()=>h.nativeGoogleRequest(`https://forms.googleapis.com/v1/forms/${FORM}`);
}
test('Google SERVICE_DISABLED identifica serviço/projeto consumidor e link seguro sem expor corpo privado',()=>{
  const h=harness(),body={error:{code:403,status:'PERMISSION_DENIED',message:'private@example.invalid SECRET_TOKEN resposta confidencial',details:[{'@type':'type.googleapis.com/google.rpc.ErrorInfo',reason:'SERVICE_DISABLED',domain:'googleapis.com',metadata:{service:'forms.googleapis.com',consumer:'projects/123456789012',activationUrl:'https://evil.invalid/SECRET_TOKEN',privateEmail:'private@example.invalid'}}]}};
  assert.throws(googleFailure(h,body),error=>{
    assert.equal(error.status,403);assert.equal(error.reason,'SERVICE_DISABLED');assert.equal(error.service,'forms.googleapis.com');assert.equal(error.consumerProject,'123456789012');
    assert.equal(error.activationUrl,'https://console.cloud.google.com/apis/library/forms.googleapis.com?project=123456789012');assert.match(error.message,/projeto consumidor 123456789012/);
    assert.ok(!(`${error.message}${JSON.stringify(error)}`).match(/private@example|SECRET_TOKEN|evil.invalid|resposta confidencial/));return true;
  });assert.equal(h.commits.length,0);
});
test('Google ACCESS_NOT_CONFIGURED também é diagnosticado sem inventar projeto quando ausente',()=>{
  const h=harness(),body={error:{details:[{'@type':'type.googleapis.com/google.rpc.ErrorInfo',reason:'ACCESS_NOT_CONFIGURED',metadata:{service:'forms.googleapis.com'}}]}};
  assert.throws(googleFailure(h,body),error=>{assert.equal(error.reason,'ACCESS_NOT_CONFIGURED');assert.equal(error.activationUrl,undefined);assert.equal(error.consumerProject,undefined);assert.match(error.message,/projeto Google Cloud associado ao Apps Script/);return true;});
});
test('Google distingue escopo Forms insuficiente de acesso negado ao arquivo',()=>{
  for(const [reason,expected]of [['ACCESS_TOKEN_SCOPE_INSUFFICIENT',/Escopo OAuth insuficiente.*auth\/forms/],['IAM_PERMISSION_DENIED',/Acesso negado à conta executora/],['ACCESS_DENIED',/Acesso negado à conta executora/]]){
    const h=harness(),body={error:{details:[{'@type':'type.googleapis.com/google.rpc.ErrorInfo',reason,metadata:{service:'forms.googleapis.com'}}]}};
    assert.throws(googleFailure(h,body),error=>{assert.equal(error.reason,reason);assert.match(error.message,expected);assert.equal(error.activationUrl,undefined);return true;});
  }
  const h=harness();assert.throws(googleFailure(h,{error:{errors:[{reason:'insufficientPermissions'}]}}),error=>error.reason==='ACCESS_TOKEN_SCOPE_INSUFFICIENT');
});
test('Google403 não JSON/razão desconhecida mantém fallback e nunca copia resposta no erro',()=>{
  for(const body of ['<html>PRIVATE_RESPONSE secret@example.invalid SECRET_TOKEN</html>',JSON.stringify({error:{message:'PRIVATE_RESPONSE SECRET_TOKEN',details:[{'@type':'type.googleapis.com/google.rpc.ErrorInfo',reason:'UNKNOWN_REASON',metadata:{service:'forms.googleapis.com',consumer:'projects/123456789012'}}]}})]){
    const h=harness();assert.throws(googleFailure(h,body),error=>{assert.equal(error.status,403);assert.equal(error.reason,'GOOGLE_FORBIDDEN');assert.match(error.message,/não informou uma causa classificada/);assert.ok(!(`${error.message}${JSON.stringify(error)}`).match(/PRIVATE_RESPONSE|SECRET_TOKEN|secret@example/));return true;});
  }
});
test('diagnóstico ignora serviço incompatível e consumidor/URL fora do formato permitido',()=>{
  for(const metadata of [{service:'evil.invalid',consumer:'projects/123456789012',activationUrl:'https://evil.invalid/secret'},{service:'forms.googleapis.com',consumer:'projects/123?token=SECRET_TOKEN',activationUrl:'https://console.cloud.google.com/?token=SECRET_TOKEN'}]){
    const h=harness();assert.throws(googleFailure(h,{error:{details:[{'@type':'type.googleapis.com/google.rpc.ErrorInfo',reason:'SERVICE_DISABLED',metadata}]}}),error=>{assert.equal(error.activationUrl,undefined);assert.equal(error.consumerProject,undefined);assert.ok(!(`${error.message}${JSON.stringify(error)}`).match(/evil.invalid|SECRET_TOKEN/));return true;});
  }
});
test('erro503 continua retryable e retorno Google bem-sucedido mantém JSON sem diagnóstico adicional',()=>{
  const h=harness();assert.throws(googleFailure(h,'PRIVATE_RESPONSE',503),error=>{assert.equal(error.status,503);assert.equal(error.reason,'GOOGLE_API_UNAVAILABLE');assert.ok(!error.message.includes('PRIVATE_RESPONSE'));return true;});
  h.ctx.UrlFetchApp={fetch:()=>({getResponseCode:()=>200,getContentText:()=>JSON.stringify({formId:FORM})})};assert.equal(h.nativeGoogleRequest(`https://forms.googleapis.com/v1/forms/${FORM}`).formId,FORM);
});
